/**
 * Migration helpers shared by the CLI (./migrate.ts), the test setup, the
 * Vercel build and the health check.
 *
 * Migrations are SQL files generated by drizzle-kit from the schema and
 * committed to Git, so every environment builds the database from exactly the
 * same, reviewable statements. They are never applied implicitly on server
 * start -- a financial system's schema changes should be a deliberate step.
 */

import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import type { Client } from '@libsql/client';
import { migrate } from 'drizzle-orm/libsql/migrator';
import { MIGRATIONS_FOLDER, type Db } from './index';

/** Drizzle records applied migrations here, keyed by the journal timestamp. */
const MIGRATIONS_TABLE = '__drizzle_migrations';

interface JournalEntry {
  idx: number;
  tag: string;
  when: number;
}

/**
 * The committed journal, set by scripts/build.mjs, so the health check in a
 * serverless function needs no migration files on disk. Undefined when
 * running from source.
 */
declare const __EMBEDDED_JOURNAL__: JournalEntry[] | undefined;

export async function runMigrations(database: Db, folder = MIGRATIONS_FOLDER): Promise<void> {
  await migrate(database, { migrationsFolder: folder });
}

function readJournal(folder: string): JournalEntry[] {
  if (folder === MIGRATIONS_FOLDER && typeof __EMBEDDED_JOURNAL__ !== 'undefined') return __EMBEDDED_JOURNAL__;
  const journalPath = join(folder, 'meta', '_journal.json');
  if (!existsSync(journalPath)) return [];
  const parsed = JSON.parse(readFileSync(journalPath, 'utf8')) as { entries?: JournalEntry[] };
  return parsed.entries ?? [];
}

export interface MigrationStatus {
  available: number;
  applied: number;
  pending: string[];
}

/**
 * Compare the committed migration journal with what the database has applied.
 * Mirrors Drizzle's own rule: a migration is pending when its journal timestamp
 * is newer than the most recently applied one.
 */
export async function getMigrationStatus(client: Client, folder = MIGRATIONS_FOLDER): Promise<MigrationStatus> {
  const journal = readJournal(folder);

  const table = await client.execute({ sql: "select 1 from sqlite_master where type = 'table' and name = ?", args: [MIGRATIONS_TABLE] });
  if (table.rows.length === 0) {
    return { available: journal.length, applied: 0, pending: journal.map((e) => e.tag) };
  }

  const result = await client.execute(`select count(*) as applied, max(created_at) as latest from ${MIGRATIONS_TABLE}`);
  const row = result.rows[0] as unknown as { applied: number; latest: number | null };
  const latest = Number(row.latest ?? 0);
  const pending = journal.filter((entry) => entry.when > latest).map((entry) => entry.tag);

  return { available: journal.length, applied: Number(row.applied), pending };
}
